//! Phase C — error / rejection surface differential tests (`ERRORS.md` rows 1-20).
//!
//! The C library has **no** error returns, no sentinels, no asserts and no
//! range checks (see `ERRORS.md` for the mechanical derivation).  Both public
//! functions return `void`.  So the contract each row below verifies is that the
//! Rust translation, driven through its `.so` exports exactly as the C is,
//! *accepts the same inputs, never rejects, never panics, never aborts*, and
//! produces the identical observable result.
//!
//! For the rows that need the full 2000-iteration pipeline (1-7, 15, 18-20) the
//! cheap observable is used here and the expensive one is in
//! `long_exec_diff.rs`; the arithmetic-corner rows (8-14, 16-17) are exercised
//! at full 262144-element width against the C `.so` in-process.

mod common;

use common::{assert_arrays_eq, load_pair, Impl, Rng, ARRAY_SIZE};
use std::ffi::c_int;

fn diff_peo(ctx: &str, c: &Impl, r: &Impl, input: &[c_int], k: usize) {
    c.set_array(input);
    r.set_array(input);
    c.peo_times(k);
    r.peo_times(k);
    assert_arrays_eq(ctx, c.array(), r.array());
    assert_eq!(c.xor(), r.xor(), "{ctx}: XOR differs");
}

/// `f` applied `n` times to a single value, computed by driving the *C* `.so`
/// (every element of the array holds a different probe, so one pass covers many).
fn c_apply(c: &Impl, probes: &[c_int], k: usize) -> Vec<c_int> {
    let mut input = vec![0i32; ARRAY_SIZE];
    for (i, slot) in input.iter_mut().enumerate() {
        *slot = probes[i % probes.len()];
    }
    c.set_array(&input);
    c.peo_times(k);
    let out = c.array().to_vec();
    (0..probes.len()).map(|i| out[i]).collect()
}

// ---------------------------------------------------------------------------
// Rows 1-5 -- the whole `unsigned int seed` domain is accepted; no clamping, no
// sign extension, no rejection.  Verified here against the recorded outputs of
// the C `.so` (see `tests/cref/`, regenerated by `tools/gen_c_refs.sh`); the
// live in-process C-vs-Rust comparison for the same seeds is in
// `long_exec_diff.rs`.
// ---------------------------------------------------------------------------

#[test]
fn rows01_05_full_seed_domain_is_accepted() {
    let _g = common::GLOBAL_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let p = load_pair();
    let refs = common::load_c_references();
    assert!(
        !refs.is_empty(),
        "no recorded C reference outputs found -- run tools/gen_c_refs.sh"
    );

    // Row 1/2: srand(0) is specified to behave as srand(1).
    for s in [0u32, 1] {
        let want = refs
            .get(&s)
            .unwrap_or_else(|| panic!("no C reference for seed {s}"));
        let got = common::capture_stdout(&format!("seed{s}"), || p.r.long_exec(s));
        assert_eq!(
            String::from_utf8_lossy(&got).trim_end(),
            want,
            "row01/02: seed {s}"
        );
    }
    assert_eq!(refs[&0], refs[&1], "row01: srand(0) must alias srand(1)");

    // Rows 3-5: UINT_MAX, 2^31, INT_MAX, 2^31+1, UINT_MAX-1 -- all accepted, all
    // distinct, none aliased or clamped.
    let boundary = [4294967295u32, 2147483648, 2147483647, 2147483649, 4294967294];
    let mut seen = std::collections::BTreeSet::new();
    for s in boundary {
        let want = refs
            .get(&s)
            .unwrap_or_else(|| panic!("no C reference for seed {s}"));
        let got = common::capture_stdout(&format!("seed{s}"), || p.r.long_exec(s));
        assert_eq!(
            String::from_utf8_lossy(&got).trim_end(),
            want,
            "rows03-05: seed {s}"
        );
        seen.insert(want.clone());
    }
    assert_eq!(
        seen.len(),
        boundary.len(),
        "rows03-05: boundary seeds must not alias each other: {seen:?}"
    );
}

// ---------------------------------------------------------------------------
// Rows 6-7 -- repeated / re-ordered `long_exec` calls in one library instance.
// Cheap surrogate: the same property for `perform_expensive_operations`, whose
// composition is what `long_exec` is built from.  The full-pipeline version is
// `long_exec_diff.rs::row_live_ordering_and_idempotence`.
// ---------------------------------------------------------------------------

#[test]
fn rows06_07_no_residual_state_between_runs() {
    let p = load_pair();
    let (c, r) = p.split();
    let mut rng = Rng::new(0x0606_0707_0606_0707);
    let mut a = vec![0i32; ARRAY_SIZE];
    let mut b = vec![0i32; ARRAY_SIZE];
    rng.fill_full_range(&mut a);
    rng.fill_full_range(&mut b);

    // Fresh-instance result for `b`.
    let fresh = {
        let q = load_pair();
        q.c.set_array(&b);
        q.c.peo_times(3);
        q.c.array().to_vec()
    };

    // Run `a` first, then `b`, in both libraries: `b`'s result must be unchanged.
    diff_peo("row07 run-a", c, r, &a, 3);
    diff_peo("row07 run-b-after-a", c, r, &b, 3);
    assert_arrays_eq("row07 residual-state leak", &fresh, c.array());
    assert_arrays_eq("row07 residual-state leak (Rust)", &fresh, r.array());

    // Row 6: the identical input run twice must give the identical output.
    diff_peo("row06 repeat-1", c, r, &a, 2);
    let first = c.array().to_vec();
    diff_peo("row06 repeat-2", c, r, &a, 2);
    assert_arrays_eq("row06 not idempotent", &first, c.array());
    assert_arrays_eq("row06 not idempotent (Rust)", &first, r.array());
}

// ---------------------------------------------------------------------------
// Row 8 -- pristine .bss (all zeros); no divide-by-zero, no special case.
// ---------------------------------------------------------------------------

#[test]
fn row08_all_zero_bss() {
    let p = load_pair();
    let (c, r) = p.split();
    assert!(c.array().iter().all(|&v| v == 0));
    assert!(r.array().iter().all(|&v| v == 0));
    c.peo();
    r.peo();
    assert_arrays_eq("row08 all-zero", c.array(), r.array());
    // And under composition.
    diff_peo("row08 all-zero k=5", c, r, &vec![0; ARRAY_SIZE], 5);
}

// ---------------------------------------------------------------------------
// Rows 9-12 -- the signed-overflow / INT_MIN / arithmetic-shift / truncating
// division corners.  A Rust translation using checked arithmetic would panic
// (abort, since the release profile sets panic = "abort"); the C wraps.
// ---------------------------------------------------------------------------

#[test]
fn rows09_12_signed_overflow_and_division_corners() {
    let p = load_pair();
    let (c, r) = p.split();

    // Row 9: INT_MIN.  x*3+7 overflows; INT_MIN<<1 == 0; INT_MIN/2 is exact;
    // x - (x<<1) yields INT_MIN back rather than the unrepresentable -INT_MIN.
    diff_peo("row09 INT_MIN", c, r, &vec![i32::MIN; ARRAY_SIZE], 1);
    diff_peo("row09 INT_MIN k=4", c, r, &vec![i32::MIN; ARRAY_SIZE], 4);

    // Row 10: INT_MAX -- overflows on the very first statement.
    diff_peo("row10 INT_MAX", c, r, &vec![i32::MAX; ARRAY_SIZE], 1);
    diff_peo("row10 INT_MAX k=4", c, r, &vec![i32::MAX; ARRAY_SIZE], 4);

    // Row 11: arithmetic >> on negatives.
    let negs: Vec<c_int> = (0..ARRAY_SIZE)
        .map(|i| -1 - ((i as c_int) & 0x3FF))
        .collect();
    diff_peo("row11 arithmetic-shift", c, r, &negs, 1);

    // Row 12: truncating division / sign-of-dividend remainder.  Probe the exact
    // documented examples through the C library and check the Rust agrees.
    let probes: Vec<c_int> = vec![
        -11, -9, -7, -6, -5, -3, -2, -1, 0, 1, 2, 3, 5, 6, 7, 9, 11, 13, 14, -13, -14, i32::MIN,
        i32::MIN + 1, i32::MAX, i32::MAX - 1, -2147483647, 6, -6, 8, -8,
    ];
    let cres = c_apply(c, &probes, 1);
    let rres = {
        let mut input = vec![0i32; ARRAY_SIZE];
        for (i, slot) in input.iter_mut().enumerate() {
            *slot = probes[i % probes.len()];
        }
        r.set_array(&input);
        r.peo();
        (0..probes.len()).map(|i| r.array()[i]).collect::<Vec<_>>()
    };
    for (i, &v) in probes.iter().enumerate() {
        assert_eq!(cres[i], rres[i], "row12: f^100({v}) C={} Rust={}", cres[i], rres[i]);
    }
}

// ---------------------------------------------------------------------------
// Row 13 -- multiples of 7 / `x % 7 == 0`.
// ---------------------------------------------------------------------------

#[test]
fn row13_modulo_seven_corner() {
    let p = load_pair();
    let (c, r) = p.split();
    let sevens: Vec<c_int> = (0..ARRAY_SIZE)
        .map(|i| ((i as c_int).wrapping_sub(131072)).wrapping_mul(7))
        .collect();
    for &v in sevens.iter().take(256) {
        assert_eq!(v % 7, 0);
    }
    diff_peo("row13 multiples-of-7", c, r, &sevens, 1);
    diff_peo("row13 multiples-of-7 k=3", c, r, &sevens, 3);
}

// ---------------------------------------------------------------------------
// Row 14 -- inputs that are already fixed points / cycle members.
// ---------------------------------------------------------------------------

#[test]
fn row14_cycle_member_inputs() {
    let p = load_pair();
    let (c, r) = p.split();
    let mut rng = Rng::new(0x1414_1414_1414_1414);
    let mut input = vec![0i32; ARRAY_SIZE];
    rng.fill_full_range(&mut input);
    c.set_array(&input);
    c.peo_times(60); // n = 6000: orbits have entered their cycles
    let deep = c.array().to_vec();
    let distinct: std::collections::BTreeSet<c_int> = deep.iter().copied().collect();
    assert!(
        distinct.len() < ARRAY_SIZE,
        "expected orbits to coalesce; got {} distinct values",
        distinct.len()
    );
    for k in [1usize, 2, 5, 13] {
        diff_peo(&format!("row14 cycle-members k={k}"), c, r, &deep, k);
    }
}

// ---------------------------------------------------------------------------
// Row 15 -- repeated calls compose with no drift and no "already done" guard.
// ---------------------------------------------------------------------------

#[test]
fn row15_composition_has_no_drift() {
    let p = load_pair();
    let (c, r) = p.split();
    let mut rng = Rng::new(0x1515_1515_1515_1515);
    let mut input = vec![0i32; ARRAY_SIZE];
    rng.fill_full_range(&mut input);

    // Step both libraries one call at a time and compare after *every* call, so a
    // divergence is attributed to the exact k at which it appears.
    c.set_array(&input);
    r.set_array(&input);
    for k in 1..=25usize {
        c.peo();
        r.peo();
        assert_arrays_eq(&format!("row15 after call {k}"), c.array(), r.array());
    }

    // k calls == one k-call run from the same start (no hidden per-call state).
    let stepwise = c.array().to_vec();
    let q = load_pair();
    q.c.set_array(&input);
    q.c.peo_times(25);
    assert_arrays_eq("row15 stepwise vs bulk (C)", &stepwise, q.c.array());
    q.r.set_array(&input);
    q.r.peo_times(25);
    assert_arrays_eq("row15 stepwise vs bulk (Rust)", &stepwise, q.r.array());
}

// ---------------------------------------------------------------------------
// Rows 16-17 -- arbitrary bit patterns written through the exported object, and
// the last slot / exact object size.
// ---------------------------------------------------------------------------

#[test]
fn rows16_17_exported_array_accepts_every_bit_pattern() {
    let p = load_pair();
    let (c, r) = p.split();

    // Row 16: uniformly random over the whole 2^32 bit space, several batches.
    let mut input = vec![0i32; ARRAY_SIZE];
    for batch in 0..3u64 {
        let mut rng = Rng::new(0x1616_0000_0000_0000 ^ batch);
        rng.fill_full_range(&mut input);
        diff_peo(&format!("row16 batch {batch}"), c, r, &input, 1);
    }

    // Row 17: the very last slot must be live and must participate in the XOR.
    let mut probe = vec![0i32; ARRAY_SIZE];
    probe[ARRAY_SIZE - 1] = 123_456_789;
    diff_peo("row17 last-slot", c, r, &probe, 1);
    let all_zero_tail = {
        let q = load_pair();
        q.c.set_array(&vec![0i32; ARRAY_SIZE]);
        q.c.peo();
        q.c.array()[ARRAY_SIZE - 1]
    };
    assert_ne!(
        c.array()[ARRAY_SIZE - 1],
        all_zero_tail,
        "row17: last slot was not processed"
    );
    assert_eq!(
        c.array()[ARRAY_SIZE - 1],
        r.array()[ARRAY_SIZE - 1],
        "row17: last slot differs"
    );
    // And the XOR reduction must include it.
    assert_eq!(c.xor(), r.xor(), "row17: XOR differs");
}

// ---------------------------------------------------------------------------
// Rows 18-19 -- printf("%d\n") formatting: signed decimal, exactly one newline,
// nothing else on stdout.
// ---------------------------------------------------------------------------

#[test]
fn rows18_19_printf_formatting() {
    let _g = common::GLOBAL_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let p = load_pair();
    let refs = common::load_c_references();
    let seed = 7u32;
    let want = refs.get(&seed).expect("C reference for seed 7");
    let got = common::capture_stdout("fmt", || p.r.long_exec(seed));
    let text = String::from_utf8(got.clone()).expect("stdout must be valid ASCII");
    assert_eq!(
        text,
        format!("{want}\n"),
        "row19: stdout must be exactly `<decimal>\\n`, got {:?}",
        text
    );
    assert_eq!(text.matches('\n').count(), 1, "row19: exactly one newline");
    assert!(!text.starts_with(' ') && !text.contains("  "), "row19: no padding");
    // Row 18: the value round-trips through `%d` as a *signed* int.
    let v: i32 = text.trim_end().parse().expect("row18: must parse as i32");
    assert_eq!(format!("{v}"), text.trim_end());
}

// ---------------------------------------------------------------------------
// Row 20 -- loop bounds: exactly ARRAY_SIZE elements, exactly ITERATIONS calls;
// no element skipped, none processed twice.
// ---------------------------------------------------------------------------

#[test]
fn row20_every_element_processed_exactly_once_per_call() {
    let p = load_pair();
    let (c, r) = p.split();
    // A unique value per slot: if any slot were skipped it would still hold its
    // input, and if any were processed twice it would hold f^200 instead of f^100.
    let input: Vec<c_int> = (0..ARRAY_SIZE).map(|i| i as c_int).collect();
    let once = {
        let q = load_pair();
        q.c.set_array(&input);
        q.c.peo();
        q.c.array().to_vec()
    };
    let twice = {
        let q = load_pair();
        q.c.set_array(&input);
        q.c.peo_times(2);
        q.c.array().to_vec()
    };
    c.set_array(&input);
    r.set_array(&input);
    c.peo();
    r.peo();
    assert_arrays_eq("row20 C f^100", &once, c.array());
    assert_arrays_eq("row20 Rust f^100", &once, r.array());
    // No slot may be skipped: a skipped slot would still hold its input, and a
    // doubly-processed slot would hold f^200 instead of f^100.  (A handful of
    // slots can legitimately coincide -- f^100(v) == v is possible for cycle
    // members -- so this is an aggregate check plus an exact per-slot compare
    // against the C result above.)
    let unchanged = (0..ARRAY_SIZE).filter(|&i| r.array()[i] == input[i]).count();
    let doubled = (0..ARRAY_SIZE).filter(|&i| r.array()[i] == twice[i]).count();
    let c_unchanged = (0..ARRAY_SIZE).filter(|&i| c.array()[i] == input[i]).count();
    let c_doubled = (0..ARRAY_SIZE).filter(|&i| c.array()[i] == twice[i]).count();
    assert_eq!(unchanged, c_unchanged, "row20: skipped-slot count differs");
    assert_eq!(doubled, c_doubled, "row20: doubled-slot count differs");
    assert!(
        unchanged * 100 < ARRAY_SIZE,
        "row20: {unchanged} slots unchanged -- the kernel did not run"
    );
    assert!(
        doubled * 100 < ARRAY_SIZE,
        "row20: {doubled} slots look processed twice"
    );
    assert_eq!(ARRAY_SIZE, 262144);
    assert_eq!(common::ITERATIONS, 2000);
}
